  ui_story_30890101_43_dialog_content = "(¿Podría lo que está sucediendo en el Coloso... estar relacionado con el gran secreto de Lumopolis?!)",
  ui_story_30890101_44_dialog_content = "Día Siguiente",
  ui_story_30890101_45_dialog_content = "¿Quieres decir que todo está arreglado ahora?",
  ui_story_30890101_46_dialog_content = "¡Eso es increíble, Irridon... Entonces, ¿qué había detrás de esas <color=#FFB400>huellas</color> y la <color=#FFB400>comida desaparecida</color>?",
  ui_story_30890101_47_dialog_content = "Tal como sospechabas, un Eclipsite de alto nivel se infiltró a bordo cuando te detuviste en esas ruinas.",
  ui_story_30890101_48_option_content = "¡¿Y lo enfrentaste solo?! ¿Estás bien?!",
  ui_story_30890101_49_dialog_content = "No estoy seguro de que sea exactamente lo que esperabas.",
  ui_story_30890101_50_dialog_content = "No tuve que luchar con eso, simplemente lo <color=#FFB400>interrogué</color>.",
  ui_story_30890101_51_option_content = "¡Un Eclipsite de alto nivel! ¿Se escapó?!",
