  ui_story_30890101_53_dialog_content = "Pero ten la seguridad de que ya no está en el Coloso.",
  ui_story_30890101_54_dialog_content = "Entonces... ¿Qué pasó?",
  ui_story_30890101_55_dialog_content = "¿No recuerdas? Tú mismo me dijiste que el Coloso se detuvo en unas ruinas anteriormente.",
  ui_story_30890101_56_dialog_content = "Sí, lo recuerdo claramente... entonces, ¿fue en ese momento cuando...",
  ui_story_30890101_57_dialog_content = "Sí, se coló a bordo.",
  ui_story_30890101_58_dialog_content = "Pero no atacó a ningún auroriano, ni robó información del Coloso.",
  ui_story_30890101_59_dialog_content = "Ahora, dime qué estás haciendo aquí o responde a mi espada.",
  ui_story_30890101_60_dialog_content = "<anim type=Shake> <size=35>Eep...</size></anim>",
  ui_story_30890101_61_dialog_content = "¡Habla!",
  ui_story_30890101_62_dialog_content = "No, por favor... Uh...",
  ui_story_30890101_63_dialog_content = "Sin sangre ni señales de combate... ¿No están aquí para emboscar a la tripulación?",
  ui_story_30890101_64_dialog_content = "Me di cuenta de que una de las despensas había sido destruida...",
  ui_story_30890101_65_dialog_content = "*Rugidos*",
  ui_story_30890101_66_dialog_content = "M-Me... Hambre... Buscar... Comida... ¡Hambriento!",
  ui_story_30890101_67_dialog_content = "Entonces... ¿Puedo... comer más...?",
  ui_story_30890101_68_dialog_content = "Comida auroriana... Mmm... Sabrosa...",
  ui_story_30890101_69_dialog_content = "Yo... No daño... ¡No daño Aurorian!",
  ui_story_30890101_70_dialog_content = "(Un Eclipsite de alto nivel... ¿que no había lastimado a nadie?)",
  ui_story_30890101_71_dialog_content = "Tú... ¿Comes? Aquí... Bien...",
  ui_story_30890101_72_dialog_content = "(Está... compartiendo su comida? Este no es un comportamiento normal de los Eclipsites...)",
  ui_story_30890101_73_dialog_content = "(He visto estos tipos especiales de Eclipsites antes: seres amables y pacíficos que pueden entender a los humanos e incluso a los Aurorians.)",
  ui_story_30890101_74_dialog_content = "(Si es uno de ellos... quizás sea mejor dejarlo aquí para observación.)",
  ui_story_30890101_75_dialog_content = "Según entiendo...",
  ui_story_30890101_76_dialog_content = "Incluso un Eclipsite merece un <color=#FFB400>juicio justo</color>. No has lastimado a nadie, así que no tengo razón para erradicarte.",
  ui_story_30890101_77_dialog_content = "¿Eh?! Boo-hoo...",
  ui_story_30890101_78_dialog_content = "Pero el robo de comida es un delito castigable... Y el Coloso podría necesitar más limpiadores.",
  ui_story_30890101_79_dialog_content = "Si insistes en comer su comida, ¡entonces limpia este lugar!",
  ui_story_30890101_80_dialog_content = "¡¿E-Eh?!",
  ui_story_30890101_81_dialog_content = "Durante mi interrogatorio, también aprendí—",
  ui_story_30890101_82_dialog_content = "Que solo se coló a bordo del Colossus y arriesgó su vida debido a su desesperada necesidad de comida.",
  ui_story_30890101_83_dialog_content = "Su comportamiento no es como el de los Eclipsites regulares, así que le di una prueba simple: limpiar el Colossus.",
  ui_story_30890101_84_dialog_content = "Y lo hizo sin dudarlo.",
  ui_story_30890101_85_dialog_content = "Un Eclipsite que disfruta comiendo comida Aurorian... Es increíble.",
  ui_story_30890101_86_option_content = "Entonces... ¿No lo mataste?",
  ui_story_30890101_87_dialog_content = "Le di comida y lo envié en su camino.",
  ui_story_30890101_88_dialog_content = "La Espada de Préstamo no matará a los inocentes... Así que le mostré piedad.",
  ui_story_30890101_89_option_content = "¡Pero aún era un Eclipsite!",
  ui_story_30890101_90_dialog_content = "Quizás un Aurorian malvado sea mucho más temible que un Eclipsite inofensivo...",
  ui_story_30890101_91_dialog_content = "Nunca dejaría libre a un auroriano si sus manos estuvieran manchadas de sangre... Y nunca mataría a un eclipsita que no haya hecho nada malo.",
  ui_story_30890101_92_dialog_content = "¿En realidad le gusta la comida rara de Vice?",
  ui_story_30890101_93_dialog_content = "Estofado de pulpo en leche... ¿Puedes siquiera llamar a eso comida? Qué preferencia perturbadora...",
  ui_story_30890101_94_dialog_content = "No importa, solo me alegra que nadie haya resultado herido.",
  ui_story_30890101_95_dialog_content = "¿Entonces todo está bien ahora?",
  ui_story_30890101_96_dialog_content = "Como dijiste, nadie resultó herido y nada fue dañado.",
  ui_story_30890101_97_dialog_content = "Entonces, todos estos sucesos extraños... ¿fueron por culpa de ese Eclipsite?",
  ui_story_30890101_98_dialog_content = "Ese parece ser el caso.",
  ui_story_30890101_99_dialog_content = "¿D-De verdad no hay nada más pasando?",
  ui_story_30890101_100_dialog_content = "Realicé una búsqueda completa del Coloso también y no encontré nada fuera de lo común.",
  ui_story_30890101_101_dialog_content = "E-Es eso así... Eso es bueno.",
  ui_story_30890101_102_dialog_content = "Todo este tiempo, pensé que tal vez tenía que ver con algunos secretos oscuros y profundos de Lumopolis... No he dormido en días.",
  ui_story_30890101_103_dialog_content = "¿Por qué pensarías eso?",
  ui_story_30890101_104_dialog_content = "Cuando le conté a Carleen sobre eso, ella se quedó pensando durante mucho tiempo antes de decir que encontraría a alguien para encargarse de ello.",
  ui_story_30890101_105_dialog_content = "Carleen tiene una... mirada seria.",
  ui_story_30890101_106_dialog_content = "Mmm...",
  ui_story_30890101_107_dialog_content = "Pensé que tal vez ella sabía algo y que no podía manejarlo por sí misma... ¡Así que solicitó a alguien tan capaz como tú!",
  ui_story_30890101_108_dialog_content = "Sea cual sea la verdad... ¡No podía evitar sentir que estaba relacionada con Lumopolis de alguna manera!",
  ui_story_30890101_109_dialog_content = "Tienes bastante imaginación.",
  ui_story_30890101_110_dialog_content = "No hay nada malo en ser cauteloso, pero el asunto se ha resuelto. Puedes estar tranquilo ahora.",
  ui_story_30890101_111_dialog_content = "Oh... Me pregunto por qué la expresión de Carleen era tan sombría, entonces...",
  ui_story_30890101_112_dialog_content = "Quizás estés pensando demasiado en las cosas.",
  ui_story_30890101_113_dialog_content = "Estoy casi seguro de que ella se preguntaba a quién llamar para este asunto.",
  ui_story_30890101_114_dialog_content = "El Salón de Justicia ha estado muy ocupado últimamente y yo estaba de vacaciones muy atrasadas.",
  ui_story_30890101_X114_dialog_content = "Rara vez tomo tiempo libre para mí, así que imagino que no quería molestarme.",
  ui_story_30890101_115_dialog_content = "Y no está en mi naturaleza rechazar a una persona necesitada o un problema que necesita solución.",
  ui_story_30890101_119_dialog_content = "El Salón de Justicia... tampoco es exactamente lo que esperaba.",
  ui_story_30890101_120_dialog_content = "Pensé que todos allí pasaban sus días leyendo documentos, trabajando en sus asuntos con esa expresión seria en sus rostros...",
  ui_story_30890101_121_dialog_content = "Pero cuando vi a ti y a los demás del Salón de la Justicia, me di cuenta de que no era así.",
  ui_story_30890101_122_dialog_content = "¿Entonces aún crees que soy ese tipo de persona? ¿Serio y duro?",
  ui_story_30890101_123_dialog_content = "Sí... ¡quiero decir no! ¡Para nada! ¡Ni siquiera un poco!",
  ui_story_30890101_124_dialog_content = "Quiero decir, ¡eres el Juez Principal de Lumopolis! Entendería si fueras así, ¡es perfectamente natural!",
  ui_story_30890101_125_dialog_content = "No te preocupes, no me sorprende que pienses de esa manera.",
  ui_story_30890101_126_dialog_content = "Tal vez también necesite hacer algunos cambios en mi vida...",
  ui_story_30890101_127_dialog_content = "¿Y si...? ¿Y si pruebo una personalidad diferente a partir de mañana? Por ejemplo, ¿un tipo divertido?",
  ui_story_30890101_128_dialog_content = "E-Eh??? Q-Quiero decir, no tiene que ser tan repentino...",
  ui_story_30890101_129_dialog_content = "Tampoco quiero que los demás me encuentren intimidante, ya sabes.",
  ui_story_30890101_130_dialog_content = "Entiendo, pero...",
  ui_story_30890101_131_dialog_content = "¡Pero estás bien tal como eres! ¡En serio!",
  ui_story_30890601_1_dialog_content = "Estás...",
  ui_story_30890601_2_dialog_content = "<color=#e8d9bb>¡Clang Clang Clang!</color>",
  ui_story_30890601_3_dialog_content = "¿Ah?",
  ui_story_30890601_4_dialog_content = "(Siempre me han asombrado los encuentros).",
  ui_story_30890601_5_dialog_content = "(Cuando consideras la inmensidad del universo y el tiempo perfecto...)",
  ui_story_30890601_6_dialog_content = "(Y la falta de esfuerzo... Un encuentro sucede, así nomás.)",
  ui_story_30890601_7_dialog_content = "(Justo como ahora.)",
  ui_story_30890601_8_dialog_content = "(Antes de esto, nunca creí en nada de eso...)",
  ui_story_30890601_9_dialog_content = "(En un lugar lejos de Astra.)",
  ui_story_30890601_10_dialog_content = "(En esta antigua estación, donde solo unos pocos lugareños de Koufu-jou suelen pisar.)",
  ui_story_30890601_11_dialog_content = "(Conocí a una chica con un magnífico atuendo local.)",
  ui_story_30890601_12_dialog_content = "(Ella hojeó las postales frente a ella, tomando una con sus dedos delgados y largos.)",
  ui_story_30890601_13_dialog_content = "(Hacía frío afuera, pero gotas de sudor brotaban de su frente.)",
  ui_story_30890601_14_dialog_content = "(Mientras caían las flores de cerezo con gracia, vi su rostro ligeramente sorprendido entre los pétalos que caían...)",
  ui_story_30890601_15_dialog_content = "¿PlayerName?",
  ui_story_30890601_16_dialog_content = "¿Juez Principal?",
  ui_story_30890601_17_dialog_content = "Qué casualidad. ¿También estás aquí de vacaciones?",
  ui_story_30890601_18_dialog_content = "¿De verdad eres tú, Juez Principal? Casi no te reconocí.",
  ui_story_30890601_19_dialog_content = "¿Qué hay con vos?",
  ui_story_30890601_20_dialog_content = "Recuerdo decirte que me llames simplemente como Irridon.",
  ui_story_30890601_21_dialog_content = "Además, esto no es Lumópolis, así que olvida quién soy.",
  ui_story_30890601_22_dialog_content = "Irri... Irridon...",
  ui_story_30890601_23_dialog_content = "*Tose* Dejaste caer una postal.",
  ui_story_30890601_24_dialog_content = "¿Eh? Olvidé que estaba sosteniendo algo en mi mano...",
  ui_story_30890601_25_dialog_content = "No te preocupes, lo conseguiré por ti.",
  ui_story_30890601_26_dialog_content = "Gracias, Irridon...",
  ui_story_30890601_27_dialog_content = "Creo que te ves realmente diferente en comparación con tu yo habitual.",
  ui_story_30890601_28_dialog_content = "¿Es por... lo que llevo puesto?",
  ui_story_30890601_29_dialog_content = "¿No es este el atuendo local de Koufu-jou?",
  ui_story_30890601_30_option_content = "¡Se ve genial!",
  ui_story_30890601_31_dialog_content = "No sé qué más decir, ¡pero creo que realmente te queda bien!",
  ui_story_30890601_32_option_content = "¡Se ve cómodo!",
  ui_story_30890601_33_dialog_content = "¡Apuesto a que es perfecto para este clima frío!",
  ui_story_30890601_34_option_content = "¡Parece caro!",
  ui_story_30890601_35_dialog_content = "... ¿En serio?",
  ui_story_30890601_36_dialog_content = "En realidad, acabo de llegar a Koufu-jou hoy y no esperaba que hiciera tanto frío aquí.",
  ui_story_30890601_37_dialog_content = "Entonces me compré un conjunto cuando me lo encontré mientras paseaba.",
  ui_story_30890601_38_dialog_content = "Ejem... Sobre eso... ¿También estás buscando conseguir algunas postales?",
  ui_story_30890601_39_dialog_content = "Bueno, escuché de los lugareños que a pesar de su ubicación remota...",
  ui_story_30890601_40_dialog_content = "Las postales en esta antigua estación son especialmente bonitas.",
  ui_story_30890601_41_dialog_content = "Y si compras una y escribes un mensaje para ti mismo... Podría hacerse realidad.",
  ui_story_30890601_42_dialog_content = "¿También escuchaste la leyenda?",
  ui_story_30890601_43_dialog_content = "Pensé que era algún tipo de anuncio promocional extraño...",
  ui_story_30890601_44_dialog_content = "Pero tal vez realmente haya algún tipo de magia en las postales aquí.",
  ui_story_30890601_45_dialog_content = "¿Qué te hace decir eso?",
  ui_story_30890601_46_dialog_content = "Solo estaba escribiendo en la postal...",
  ui_story_30890601_47_dialog_content = "\"Espero ver a mi persona predestinada en mi viaje.\"",
  ui_story_30890601_48_dialog_content = "¡¿Qué?!",
  ui_story_30890601_49_dialog_content = "<color=#e8d9bb>Zumbido, zumbido...</color>",
  ui_story_30890601_50_dialog_content = "Lo siento, es mi comunicador... Un momento, por favor.",
  ui_story_30890601_51_dialog_content = "Noche Blanca en lo alto. ¿En qué puedo ayudarte, Michenny?",
  ui_story_30890601_52_dialog_content = "(Parece... que el Juez Principal está siendo mucho más amable hoy en comparación con lo habitual.)",
  ui_story_30890601_53_dialog_content = "(¿Es esta la magia de unas vacaciones?)",
  ui_story_30890601_54_dialog_content = "¿Ohh? ¿Una nueva pista en el caso de robo de Raphael?",
  ui_story_30890601_55_dialog_content = "¿Quieres decir... está relacionado con ella?",
  ui_story_30890601_56_dialog_content = "(¿Recibió alguna mala noticia? La expresión de Irridon se volvió repentinamente solemne...)",
  ui_story_30890601_57_dialog_content = "Bueno, umm, está bien. Ya veo, resulta que yo... *Tose*.",
  ui_story_30890601_58_dialog_content = "(... ¿Por qué me miró y se volteó?)",
  ui_story_30890601_59_dialog_content = "Perdón por hacerte esperar.",
  ui_story_30890601_60_dialog_content = "Irridon, ¿está todo... bien?",
  ui_story_30890601_61_dialog_content = "¿Por qué preguntas?",
  ui_story_30890601_62_dialog_content = "Nada. Tal vez solo sea yo...",
  ui_story_30890601_63_dialog_content = "¿Te recordó algo que hiciste?",
  ui_story_30890601_64_dialog_content = "No nada...",
  ui_story_30890601_65_dialog_content = "(Ella ha vuelto como Juez Principal...? Claramente es una persona diferente a la de hace un momento.)",
  ui_story_30890601_66_dialog_content = "¿Por qué no piensas un poco más? ¿Estás seguro de que no has hecho nada?",
  ui_story_30890601_67_dialog_content = "Bueno... En realidad, se suponía que debía terminar el resto del trabajo hoy...",
  ui_story_30890601_68_dialog_content = "Pero en cambio, me salté el trabajo y estoy deambulando por aquí.",
  ui_story_30890601_69_dialog_content = "Entonces, ¿te saltaste el trabajo?",
  ui_story_30890601_70_dialog_content = "Pero creo que hay algo más. Intenta pensar otra vez.",
  ui_story_30890601_71_dialog_content = "Ayer, Vice cocinó e hice como que comía, pero en realidad no lo hice...",
  ui_story_30890601_72_dialog_content = "¿Algo más?",
  ui_story_30890601_73_dialog_content = "No respondí al correo de Charon...",
  ui_story_30890601_74_dialog_content = "Acepté un regalo de un desconocido...",
  ui_story_30890601_75_dialog_content = "No me lavé la cara en la mañana...",
  ui_story_30890601_76_dialog_content = "Espera... ¿Qué dijiste?",
  ui_story_30890601_77_dialog_content = "Lo siento... No me lavé la cara esta mañana.",
  ui_story_30890601_78_dialog_content = "Aunque esto es impactante, ¿qué dijiste antes de esto?",
  ui_story_30890601_79_dialog_content = "Acepté un regalo... ¿de un desconocido?",
  ui_story_30890601_80_dialog_content = "¿Dónde? ¿Cuándo?",
  ui_story_30890601_81_dialog_content = "En... Lumópolis. Justo el otro día, era la noche antes de irme de Lumópolis.",
  ui_story_30890601_82_dialog_content = "¿Dónde está el regalo ahora?",
  ui_story_30890601_83_dialog_content = "¡Achuuu!",
  ui_story_30890601_84_dialog_content = "¿Tienes frío?",
  ui_story_30890601_85_dialog_content = "Tal vez... y probablemente estoy vestido de menos.",
  ui_story_30890601_86_dialog_content = "¿Por qué no conseguir otro atuendo?",
  ui_story_30890601_87_dialog_content = "(No puedo simplemente decirle que no tengo suficiente dinero...)",
  ui_story_30890601_88_dialog_content = "*Tose* Sé que está un poco desordenado, pero... aquí está la bodega.",
  ui_story_30890601_89_dialog_content = "Después de recibir el regalo, ¿lo abriste para ver qué había dentro?",
  ui_story_30890601_90_dialog_content = "Tenía miedo de que fuera una de esas bromas, así que lo guardé en el almacén...",
  ui_story_30890601_91_dialog_content = "¿Sueles recibir regalos de bromistas?",
  ui_story_30890601_92_dialog_content = "*Tose* Eso... no es el punto.",
  ui_story_30890601_93_dialog_content = "¿Hay... algo malo con el regalo que recibí?",
  ui_story_30890601_94_dialog_content = "Recientemente, una banda de ladrones cometió una serie de robos en Lumopolis.",
  ui_story_30890601_95_dialog_content = "¡Así que el regalo que recibiste podría ser bienes robados!",
  ui_story_30890601_96_dialog_content = "Achu... ¡Iré a buscarlo!",
  ui_story_30890601_97_dialog_content = "¿Es ese el de tu izquierda?",
  ui_story_30890601_98_dialog_content = "Déjame ver...",
  ui_story_30890601_99_dialog_content = "<color=#e8d9bb>¡Ding! ¡Dang! ¡Clang! ¡Bang!</color>",
  ui_story_30890601_100_dialog_content = "*Tos* ¿Quién puso todas estas partes de máquinas rotas aquí...?",
  ui_story_30890601_101_dialog_content = "¿No es eso...? Ahí, frente a ti.",
  ui_story_30890601_102_dialog_content = "<color=#e8d9bb>¡Ding! ¡Dang! ¡Clang! ¡Bang!</color>",
  ui_story_30890601_103_dialog_content = "¿Qué es esa cosa parecida a una abrazadera?",
  ui_story_30890601_104_dialog_content = "¡Jaja, este es mi apreciado agarrador! ¡Lo uso para probar mi fuerza de vez en cuando!",
  ui_story_30890601_105_dialog_content = "¿Eh? ¡¿Por qué es tan fácil esto?!",
  ui_story_30890601_106_dialog_content = "Achooo... No me di cuenta de que me había vuelto más fuerte.",
  ui_story_30890601_107_dialog_content = "Espera, esto no puede ser. ¡Alguien debe haber estropeado mi pinza!",
  ui_story_30890601_108_dialog_content = "... Creo que deberías limpiarte la nariz primero.",
  ui_story_30890601_109_dialog_content = "¡Achooo! Gracias por su recordatorio, Juez Principal...",
  ui_story_30890601_110_dialog_content = "¿Qué es esa caja a tu derecha?",
  ui_story_30890601_111_dialog_content = "¡Ah, sí! ¡Eso es! Es el regalo que recibí del desconocido.",
  ui_story_30890601_112_dialog_content = "¡Déjame traértelo para que lo inspecciones!",
  ui_story_30890601_113_dialog_content = "No te apresures y ten cuidado de mirar hacia dónde vas.",
  ui_story_30890601_114_dialog_content = "<color=#e8d9bb>¡Ding! ¡Dang! ¡Clang! ¡Bang!</color>",
  ui_story_30890601_115_dialog_content = "<size=45><color=#e8d9bb>¡Auge—!</color></size>",
  ui_story_30890601_116_dialog_content = "... PlayerName, ¿estás bien?",
  ui_story_30890601_117_dialog_content = "Lo siento mucho, Juez Principal.",
  ui_story_30890601_118_dialog_content = "Caí justo encima del regalo y parece que lo aplasté.",
  ui_story_30890601_119_dialog_content = "Pero es extraño. A pesar de que me caí...",
  ui_story_30890601_120_dialog_content = "No estoy herido en absoluto...",
  ui_story_30890601_121_dialog_content = "¡Y mi espalda ya no está adolorida, mis piernas no duelen y ni siquiera siento ganas de estornudar!",
  ui_story_30890601_122_dialog_content = "Qué está sucediendo...?",
  ui_story_30890601_123_dialog_content = "¿No entiendes? Explotó y te sanó. ¿Qué crees que es?",
  ui_story_30890601_124_dialog_content = "¿Podría ser... el Cartucho de Agua Bendita de Raphael?!",
  ui_story_30890601_125_dialog_content = "¿Quieres decir que el desconocido vestido de negro era Raphael?",
  ui_story_30890601_126_dialog_content = "Si te lo dio Raphael, no habría necesidad de que yo realice una investigación.",
  ui_story_30890601_127_dialog_content = "Tienes razón, se necesitarían varios Raphaels apilados uno encima del otro para ser tan altos como el desconocido.",
  ui_story_30890601_128_dialog_content = "Entonces, ¿estás diciendo que un extraño robó las cosas de Raphael y me las dio? Pero, ¿por qué...?",
  ui_story_30890601_129_dialog_content = "¿Recuerdas algo más sobre el extraño?",
  ui_story_30890601_130_dialog_content = "Recuerdo que el extraño estaba envuelto completamente de cabeza a pies en negro.",
  ui_story_30890601_131_dialog_content = "Y caminaban tambaleándose, como si su parte superior e inferior del cuerpo no estuvieran conectadas.",
  ui_story_30890601_132_dialog_content = "Después de pasarme el regalo, simplemente se dieron la vuelta y se alejaron...",
  ui_story_30890601_133_dialog_content = "Tambaleante... ¿Oliste algún alcohol?",
  ui_story_30890601_134_dialog_content = "En absoluto... Pero justo antes de que el extraño se fuera, ¡escuché a un cuervo como una gallina!",
  ui_story_30890601_135_dialog_content = "Ahora que lo pienso, ¡es realmente extraño!",
  ui_story_30890601_136_dialog_content = "Entiendo...",
  ui_story_30890601_137_dialog_content = "Juez Principal... ¿Sabe quién era el desconocido de negro?",
  ui_story_30890601_138_dialog_content = "Solo hay uno que me viene a la mente, y ese es...",
  ui_story_30890601_139_dialog_content = "Keating!",
  ui_story_30890601_140_dialog_content = "Keating? ¿Cómo? Tendrías que apilarlos para que sean tan altos como ese desconocido de negro...",
  ui_story_30890601_141_dialog_content = "Espera, ¿quieres decir que se apilaron para interpretar al extraño de negro?!",
  ui_story_30890601_142_dialog_content = "Pero, ¿por qué se esforzaron tanto para darme un regalo así...?",
  ui_story_30890601_143_dialog_content = "El motivo sigue siendo una pregunta... ¿Viste si había algún mensaje en la caja del regalo?",
  ui_story_30890601_144_dialog_content = "Déjame ver... Espera... ¡Realmente hay una nota! Dice...",
  ui_story_30890601_145_dialog_content = "\"Querida persona pobre y desdichada. No estés triste más.\"",
  ui_story_30890601_146_dialog_content = "\"Aquí tienes un regalo para ayudarte a ser rico.\"",
  ui_story_30890601_147_dialog_content = "\"De: GNITAEK.\"",
  ui_story_30890601_148_dialog_content = "Vale... Incluso yo estoy convencido de que es Keating ahora.",
  ui_story_30890601_149_dialog_content = "*suspiros* Esos niños...",
  ui_story_30890601_150_dialog_content = "Parece que necesitan una educación adecuada... Para que hagan el bien de manera correcta y honesta.",
  ui_story_30890601_151_dialog_content = "Pero ¿por qué? ¿Por qué piensan que necesito ayuda?",
  ui_story_30890601_152_dialog_content = "¿Es porque siempre llevo la misma ropa? Pero...",
  ui_story_30890601_153_dialog_content = "¡Noche Blanca en lo alto! Declaro oficialmente este caso como cerrado.",
  ui_story_30890601_154_dialog_content = "¡Jaja! ¡Vamos, PlayerName!",
  ui_story_30890601_155_dialog_content = "¿Eh? ¿A dónde? ¿Te refieres a...?",
  ui_story_30890601_156_option_content = "¿La prisión de Lumopolis?",
  ui_story_30890601_157_dialog_content = "Bueno, ya sé que fue un malentendido.",
  ui_story_30890601_158_dialog_content = "Esta es una rara vacación, así que continuemos nuestro viaje a Koufu-jou.",
  ui_story_30890601_159_option_content = "¿La estación que vende postales?",
  ui_story_30890601_160_dialog_content = "Ahh, no has tenido la oportunidad de comprar nada debido al malentendido de hace un momento, ¿verdad?",
  ui_story_30890601_161_dialog_content = "Está bien, sin embargo...",
  ui_story_30890601_162_dialog_content = "Por favor, no te preocupes por el dinero. ¡Hoy todo corre por mi cuenta!",
  ui_story_30890601_163_dialog_content = "¿...realmente todos piensan que estoy sin un centavo...?",
  ui_story_30890602_1_dialog_content = "<color=#e8d9bb>Wuuuush—</color>",
  ui_story_30890602_2_dialog_content = "(Una suave brisa sopla en el aire. Frente a mí hay una chica con ojos y cabello tan dorados y ardientes como el sol.)",
  ui_story_30890602_3_dialog_content = "(Para todos los demás, ella es una Jueza Principal altiva, distante y sin sonrisa.)",
  ui_story_30890602_4_dialog_content = "(Pero ahora mismo, ella me está mostrando un lado completamente diferente de ella, uno que mantiene bien oculto bajo su máscara...)",
  ui_story_30890602_5_dialog_content = "PlayerName...",
  ui_story_30890602_6_dialog_content = "¿Está realmente bien?",
  ui_story_30890602_7_dialog_content = "<color=#e8d9bb>Antes ese mismo día</color>",
  ui_story_30890602_8_dialog_content = "Resoplan... ¡Perdón por la espera!",
  ui_story_30890602_9_dialog_content = "No necesitas disculparte. No estuve esperando mucho tiempo.",
  ui_story_30890602_10_dialog_content = "En todo caso, debería agradecerte por acompañarme a tomar una taza de té.",
  ui_story_30890602_11_dialog_content = "Ejem, para ser honesto, he querido visitarte desde hace un tiempo, solo para asegurarme de que estás bien.",
  ui_story_30890602_12_dialog_content = "Te hice preocuparte, ¿verdad...?",
  ui_story_30890602_13_dialog_content = "Pero puedo asegurarte que estoy perfectamente bien. Además, como juez superior de Lumopolis, no puedo permitirme ser derrotado fácilmente.",
  ui_story_30890602_14_dialog_content = "Después de despertar de ese largo y confuso sueño, creo que finalmente he encontrado mi camino a seguir en el futuro.",
  ui_story_30890602_15_dialog_content = "Uno a uno, estoy comenzando a resolver lentamente los problemas de mi pasado que una vez me hicieron sentir indefenso y perdido.",
  ui_story_30890602_16_dialog_content = "Antes me obligaba a ser el juez principal perfecto, uno que fuera digno de las esperanzas y expectativas de todos. Pero ahora...",
  ui_story_30890602_17_dialog_content = "Finalmente me doy cuenta de que ya no tengo que fingir ser alguien más. Soy quien soy, y eso es más que suficiente.",
  ui_story_30890602_18_dialog_content = "Así que gracias, PlayerName. Gracias por despertarme de esa pesadilla.",
  ui_story_30890602_19_option_content = "¡De nada!",
  ui_story_30890602_20_dialog_content = "¡Solo estaba haciendo lo que debía hacer!",
  ui_story_30890602_21_option_content = "No hace falta que me agradezcas...",
  ui_story_30890602_22_dialog_content = "Realmente no hice nada... ¡Tú eres el que se salvó a sí mismo!",
  ui_story_30890602_23_dialog_content = "¡Jajaja! Tan humilde como siempre.",
  ui_story_30890602_24_dialog_content = "Cambiando de tema, esperaba que pudieras acompañarme a ver a cierta persona hoy.",
  ui_story_30890602_25_dialog_content = "Todavía me siento un poco culpable y simplemente no puedo dar ese primer paso por mi cuenta.",
  ui_story_30890602_26_dialog_content = "Oh... ¿Es por eso que llevas un atuendo diferente hoy?",
  ui_story_30890602_27_dialog_content = "Sí. Estas son mis viejas ropas de cuando era caballero. Me sorprende que todavía me queden tan bien después de todos estos años.",
  ui_story_30890602_28_dialog_content = "Pero incluso en aquel entonces, seguía evitando el problema que había enterrado profundamente en mi corazón.",
  ui_story_30890602_29_dialog_content = "Han pasado años y la gente ha cambiado, pero el problema sigue estrechamente vinculado a ese lugar.",
  ui_story_30890602_30_dialog_content = "Si mi pesadilla me mostró algo, es que ha llegado el momento de enfrentarme a mis demonios y resolver este problema de una vez por todas.",
  ui_story_30890602_31_dialog_content = "Pero sin ti allí para cuidarme, me temo que no tendré el valor para hacerlo.",
  ui_story_30890602_32_dialog_content = "Ya has derrotido a tu pesadilla y recuperado tu verdadero ser... ¿Qué más podría asustarte ahora?",
  ui_story_30890602_33_option_content = "A menos que...",
  ui_story_30890602_34_dialog_content = "¿Es tu padre?",
  ui_story_30890602_35_dialog_content = "Sí.",
  ui_story_30890602_36_option_content = "Simplemente no lo entiendo...",
  ui_story_30890602_37_dialog_content = "Es... mi padre.",
  ui_story_30890602_38_dialog_content = "Me avergüenza decir esto, pero aunque mi padre murió para protegerme... nunca he ido a rendirle homenaje en su tumba. Ni siquiera una vez.",
  ui_story_30890602_39_dialog_content = "Yo... Todavía no puedo enfrentarme a él. Cada vez que paso por el cementerio, me siento obligado a caminar lo más rápido posible.",
  ui_story_30890602_40_dialog_content = "Pero ahora... Tienes algo importante que decirle a él, ¿verdad?",
  ui_story_30890602_41_dialog_content = "Lo sé, y es algo que debe decirse... Pero aún tengo miedo.",
  ui_story_30890602_42_dialog_content = "¡Entonces iré contigo! Aunque no obtengamos una respuesta de él ahora, el simple hecho de decírselo debería proporcionarte la respuesta que necesitas.",
  ui_story_30890602_43_dialog_content = "PlayerName... Sabía que tenía razón al pedirte ayuda.",
  ui_story_30890602_44_dialog_content = "¿Piensas traerle algo?",
  ui_story_30890602_45_dialog_content = "Emm... No. A papá siempre le disgustaba recibir regalos, especialmente los valiosos.",
  ui_story_30890602_46_dialog_content = "Pero, ¿cómo puede alguien odiar recibir un regalo? Hmm... ¿Tenía algún pasatiempo en el pasado?",
  ui_story_30890602_47_dialog_content = "No realmente. La pasión de Papá siempre fue su trabajo, pero cuando no estaba trabajando, cuidaba las flores en este jardín...",
  ui_story_30890602_48_dialog_content = "A veces, incluso sentía celos de esas flores. La única vez que mi padre mostró algo de compasión fue cuando las cuidaba.",
  ui_story_30890602_49_dialog_content = "Y, ¿eres tú el encargado de cuidar estas flores ahora?",
  ui_story_30890602_50_dialog_content = "Sí... Irónico, ¿no?",
  ui_story_30890602_51_dialog_content = "¡Para nada! ¡Estas flores se ven saludables y hermosas para mí!",
  ui_story_30890602_52_dialog_content = "Entonces, ¿por qué no eliges algunos para tu papá? Así, él también puede ver lo bien que los has cuidado.",
  ui_story_30890602_53_dialog_content = "¿Es así...?",
  ui_story_30890602_54_dialog_content = "\"Aquí yace Rodell Novek...\" Irridon, ¡lo encontré!",
  ui_story_30890602_55_dialog_content = "¿Eh? Oye, ¿estás bien...?",
  ui_story_30890602_56_dialog_content = "...",
  ui_story_30890602_57_dialog_content = "Sé que esto debe ser realmente difícil para ti. Puedo acompañarte de regreso, si eso es lo que quieres...",
  ui_story_30890602_58_dialog_content = "No, PlayerName. Creo que finalmente estoy listo.",
  ui_story_30890602_59_dialog_content = "Uf...",
  ui_story_30890602_60_dialog_content = "Hola, padre. Soy yo, Irridon... Lo siento por tardar tanto. Finalmente reuní el valor para verte.",
  ui_story_30890602_61_dialog_content = "Todos estos años, solo pensar en enfrentarte me llenaba de vergüenza. Temía que aún me vieras como \"inútil\" por no mostrar crecimiento.",
  ui_story_30890602_62_dialog_content = "Todavía no entiendo por qué sacrificarías tu propia vida para salvar a una persona \"inútil\" como yo...",
  ui_story_30890602_63_dialog_content = "Pero rezo para que un día, cuando finalmente esté a la altura de tus expectativas, ¡pueda decir que lo hice con la cabeza en alto!",
  ui_story_30890602_64_dialog_content = "Lamentablemente... Parece que ese día aún está muy lejos.",
  ui_story_30890602_65_dialog_content = "Pero incluso así, ya no tengo miedo. Quería decirte que después de todos estos años... ya no soy tan inútil como pensaba.",
  ui_story_30890602_66_dialog_content = "Ahora soy el Juez Principal, alguien seguro tanto en sus metas como en sus convicciones.",
  ui_story_30890602_67_dialog_content = "Aunque no sea exactamente quien querías que fuera, seguiré esforzándome por convertirme en la mejor versión de mí mismo...",
  ui_story_30890602_68_dialog_content = "Porque al igual que tú, Papá... No deseo nada más que proteger esta pura y hermosa ciudad en el cielo.",
  ui_story_30890602_69_dialog_content = "Por fin entiendo ahora. Nunca me odiaste; simplemente estabas usando el método más indirecto de mostrar tu amor por mí...",
  ui_story_30890602_70_dialog_content = "Por favor, sigue cuidando de mí. Voy a seguir avanzando... pero a mi manera.",
  ui_story_30890602_71_dialog_content = "Realmente creo... que esta es la mejor manera de recompensarte...",
  ui_story_30890602_72_dialog_content = "<color=#e8d9bb>Wuuuush—</color>",
  ui_story_30890602_73_dialog_content = "PlayerName... ¿Realmente está bien?",
  ui_story_30890602_74_option_content = "¡Claro!",
  ui_story_30890602_75_option_content = "¡Fue perfecto!",
  ui_story_30890602_76_dialog_content = "¡Estoy seguro de que te escuchó, alto y claro!",
  ui_story_30890602_77_dialog_content = "Tienes razón... Estoy seguro de que escuchó cada palabra."
}
return config
